#include <Kokkos_Core.hpp>

struct Point {
	double x, y;
};

double distance(Point const& p1, Point const& p2) {
	return std::sqrt(std::pow(p2.x-p1.x, 2) + std::pow(p2.y-p1.y, 2));
}

/* Return the distance between the closest two points in the vector points.
   Use Kokkos to compute in parallel. Assume Kokkos has already been initialized.
   Example: 

   input: [{2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}]
   output: 1.41421
*/
double closestPair(Kokkos::View<const Point*> &points) {

generated_output:
double min_dist = std::numeric_limits<double>::max();

	Kokkos::parallel_reduce(points.size(),
		KOKKOS_LAMBDA(int i, double &update) {
			for (int j = i + 1; j < points.size(); j++) {
				double dist = distance(points[i], points[j]);
				update = std::min(update, dist);
			}
		},
		min_dist);

	return min_dist;
}

