/* Return the product of the vector x with every odd indexed element inverted.
   i.e. x_0 * 1/x_1 * x_2 * 1/x_3 * x_4 ...
   Use MPI and OpenMP to compute product in parallel. Assume MPI has already been initialized.
   Every rank has a complete copy of x. Return the product on all ranks.
   Example:

   input: [4, 2, 10, 4, 5]
   output: 25
*/
double productWithInverses(std::vector<double> const& x) {

generated_output:
int rank, size;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    int n = x.size();
    int n_per_rank = n / size;
    int n_remainder = n % size;

    int start = rank * n_per_rank;
    int end = start + n_per_rank;

    double product = 1;
    for (int i = start; i < end; i += 2) {
        product *= x[i];
    }

    if (n_remainder > 0) {
        if (rank < n_remainder) {
            product *= x[end + rank];
        }
    }

    double total_product;
    MPI_Allreduce(&product, &total_product, 1, MPI_DOUBLE, MPI_PROD, MPI_COMM_WORLD);

    return total_product;
}

